import numpy as np
import timeit
from numba import njit
import jax
import jax.numpy as jnp

n = 5000
vec1 = np.random.rand(n)
vec2 = np.random.rand(n)

def ref(v1, v2):
    return np.outer(v1, v2)

def opt1(v1, v2):
    return v1[:, None] * v2

def opt2(v1, v2):
    return np.einsum('i,j->ij', v1, v2)

def opt3(v1, v2):
    return np.multiply.outer(v1, v2)

@njit(fastmath=True)
def opt4(v1, v2):
    return np.outer(v1, v2)

@njit(fastmath=True)
def opt5(v1, v2):
    n = len(v1)
    res = np.empty((n, n), dtype=v1.dtype)
    for i in range(n):
        res[i, :] = v1[i] * v2
    return res

@jax.jit
def opt6(v1, v2):
    return jnp.outer(v1, v2)

_ = opt4(vec1[:10], vec2[:10])
_ = opt5(vec1[:10], vec2[:10])
_ = opt6(jnp.array(vec1[:10]), jnp.array(vec2[:10]))

funcs = [ref, opt1, opt2, opt3, opt4, opt5]
for f in funcs:
    print(f.__name__)
    try:
        t = timeit.timeit(lambda: f(vec1, vec2), number=10)
        print(f"{t:.4f}")
    except Exception as e:
        print(e)

v1_j = jnp.array(vec1)
v2_j = jnp.array(vec2)
t = timeit.timeit(lambda: opt6(v1_j, v2_j).block_until_ready(), number=10)
print(f"opt6 (JAX): {t:.4f}")
