import numpy as np
import timeit
import scipy.linalg.blas as blas

n = 5000
vec1 = np.random.rand(n)
vec2 = np.random.rand(n)

def ref(v1, v2):
    return np.outer(v1, v2)

def opt_dot(v1, v2):
    return np.dot(v1.reshape(-1, 1), v2.reshape(1, -1))

def opt_matmul(v1, v2):
    return np.matmul(v1.reshape(-1, 1), v2.reshape(1, -1))

def opt_blas(v1, v2):
    return blas.dger(1.0, v1, v2)

def opt_out(v1, v2):
    out = np.empty((len(v1), len(v2)), dtype=v1.dtype)
    return np.multiply(v1[:, None], v2, out=out)

funcs = [ref, opt_dot, opt_matmul, opt_blas, opt_out]
for f in funcs:
    print(f.__name__)
    try:
        t = timeit.timeit(lambda: f(vec1, vec2), number=100)
        print(f"{t:.4f}")
    except Exception as e:
        print(e)
