import numpy as np
import timeit
import torch

for n in [100, 5000]:
    print(f"\n--- n={n} ---")
    vec1 = np.random.rand(n)
    vec2 = np.random.rand(n)
    v1_t = torch.from_numpy(vec1)
    v2_t = torch.from_numpy(vec2)

    def ref(v1, v2):
        return np.outer(v1, v2)

    def opt1(v1, v2):
        return v1[:, None] * v2

    def opt2(v1, v2):
        return np.multiply(v1[:, None], v2)

    def opt_torch(v1, v2):
        return torch.outer(v1_t, v2_t).numpy()

    funcs = [ref, opt1, opt2, opt_torch]
    num_iters = 100000 if n == 100 else 100
    for f in funcs:
        try:
            t = timeit.timeit(lambda: f(vec1, vec2), number=num_iters)
            print(f"{f.__name__}: {t:.4f}")
        except Exception as e:
            print(e)
